"""Count ERROR lines per service in app.log."""
import json


def main():
    counts = {}
    with open("app.log") as stream:
        for line in stream:
            parts = line.split()
            if len(parts) >= 3 and parts[1] == "ERROR":
                counts[parts[2]] = counts.get(parts[2], 0) + 1
    with open("errors.json", "w") as stream:
        json.dump(dict(sorted(counts.items())), stream)


if __name__ == "__main__":
    main()
